archetypes.cards:
cards — 2–4 columns of "problem → fix". The problem lands first; the fix rises into the card when spoken.
data: { items: [{ title: "Usage runs out", sub?, icon?: "key"|"shield"|..., tag?: "RISK", fix: "Keep checks cheap, cap runs", at?, fixAt? }],
        fixLabel?: "THE FIX", source? }

archetypes.chapter:
chapter — full-screen chapter opener for long videos: a huge index numeral, the title, a one-line promise,
and the chapter rail (every chapter scene in the episode) with a marker sliding to this one. Pair with "trans": "wipe".
data: { n?: 2, title: "The handoff", sub?: "What a good brief contains", kicker?: "Chapter", short?: "Handoff" (rail label) }

archetypes.checklist:
checklist — the call to action. Steps tick off; a gate unlocks at the end; resources point to the description.
data: { title?: "Start tonight", items: [{ text, sub?, at? }], gate?: { text: "Then turn on the routine", at? },
        resources?: { title?: "In the description", items: ["house-style SKILL.md", "bootstrap.sh"] } }

archetypes.grid:
grid — a storyboard / shot list / gallery of tiles that pop in on their beat, with an optional approve bar.
data: { cols?: 4, items: [{ label: "Pill idle", glyph?: "pill"|"dot"|"spinner"|"check"|"play"|"bar"|"done"|"text:Aa", image?, at? }],
        footer?: { text: "Nothing gets built until you approve it", button?: "Approve", at? } }

archetypes.hero:
hero — episode opener. Proof first: the finished result fills the frame, then shrinks beside the title.
No footage? Give it a "stack": floating UI cards on the right that tell the story in three beats.
data: {
  proof?: { image: "media/proof.jpg" } | { frames: "media/proof/%04d.jpg", count: 90, fps: 30 },  label?: "Made overnight · No After Effects", until?: phrase|sec (default 2.6s)
  stack?: [{ kind: "msg", text } | { kind: "tool", text, sub?, who? } | { kind: "pr", id, title, ok? } | { kind: "note", text }],
  logos?: [{ name: "Grok Bot", mark: "grok"|"dot", color }], title: "An *overnight*\nmotion design studio", meta?: "five bots · one cloud computer", cast?: true }

archetypes.loop:
loop — a cycle. Nodes sit on an ellipse, arcs draw in as each node is named, then a glowing token keeps circling;
the centre states the exit condition and can count rounds.
data: { nodes: [{ label: "Brief", sub?: "what + proof", icon?: "chat"|"bolt"|..., cast?, at? }],
        center?: { text: "Until the goal is met", sub?, at? }, rounds?: [{ at, label: "Round 2" }], speed?: .16 }

archetypes.roster:
roster — the cast, one card per role, each lighting up when it is named. A runner travels the rail.
data: { from?: "Request", to?: "Delivered", items: [{ cast: "director", role: "PLAN", desc: "Owns it end to end", at?: "Director",
         lines?: ["Brief", "Storyboard"] | code?: "frame(t) {...}" | big?: "8.6" }] }

archetypes.statement:
statement — full-bleed kinetic type. For hooks, turns and one-line verdicts ("That's a demo.").
data: { eyebrow?, lines: [{ text: "That's a *demo*.", at? }], sub?: {text, at?}, align?: 'left'|'center', size?: 112, color? }
  *word* = highlighter sweep. Each line enters word by word at its moment (at = phrase or seconds).

archetypes.stats:
stats — big honest numbers. Up to 4 counters on top, optional comparison bars below, and a source tag.
data: { items: [{ label: "CPU", value: 8, prefix?: "~", suffix?: " cores", dec?: 0, sub?, tone?: "bad"|"good", at? }],
        bars?: [{ label: "Draft", value: 48, max?: 360, suffix?: " s", at? }], source? }

archetypes.terminal:
terminal — a checklist on the left ticks off while a real-looking terminal types on the right.
data: { list?: { title, items: [{ text, sub?, at? }] }, term: { title: "/workspace/studio", cmd: "bash bootstrap.sh", at?,
         out: [{ text: "✓ ffmpeg", cls?: "g"|"d"|"y"|"r"|"p", at? }], progress?: { label: "576 / 3,600 frames", at?, to? } } }

archetypes.timeline:
timeline — dated events on a horizontal track. The track fills to each event as it is named; cards alternate above
and below; an optional "now" marker closes it.
data: { events: [{ date: "Aug 11", label: "Grok Bot beta launches", sub?, at?, tone? }], now?: { label: "Today", at? } }
